struct Node {
    int data;
    Node* left;
    Node* right;
    int height;

    Node(int val) {
        data = val;
        left = nullptr;
        right = nullptr;
        height = 0; // A new leaf node starts with height 0
    }
};

// Helper to safely get the height of a node
int getHeightOfNode(Node* node) {
    if (node == nullptr) return -1; // Empty node has height -1
    return node->height;
}

// Helper to get the Balance Factor of a node
int getBalanceOfNode(Node* node) {
    if (node == nullptr) return 0;
    return getHeightOfNode(node->left) - getHeightOfNode(node->right);
}

// Single Right Rotation around node y (LL Case)
Node* LLRoation(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = 1 + std::max(getHeightOfNode(y->left), getHeightOfNode(y->right));
    x->height = 1 + std::max(getHeightOfNode(x->left), getHeightOfNode(x->right));

    // Return the new root of this subtree
    return x;
}

// Single Left Rotation around node y (RR Case)
Node* RRrotation(Node* y) {
    Node* x = y->right;
    Node* T2 = x->left;

    // Perform rotation
    x->left = y;
    y->right = T2;

    // Update heights
    y->height = 1 + std::max(getHeightOfNode(y->left), getHeightOfNode(y->right));
    x->height = 1 + std::max(getHeightOfNode(x->left), getHeightOfNode(x->right));

    // Return the new root of this subtree
    return x;
}

// Double Left-Right Rotation (LR Case)
Node* LRrotation(Node* y) {
    y->left = RRrotation(y->left);
    return LLRoation(y);
}

// Double Right-Left Rotation (RL Case)
Node* RLrotation(Node* y) {
    y->right = LLRoation(y->right);
    return RRrotation(y);
}

Node* insert(Node* node, int data) {
    // 1. Perform standard BST insertion
    if (node == nullptr) {
        return new Node(data);
    }

    if (data < node->data) {
        node->left = insert(node->left, data);
    } else if (data > node->data) {
        node->right = insert(node->right, data);
    } else {
        return node; // Duplicate keys are not allowed
    }

    // 2. Update height of this ancestor node
    node->height = 1 + std::max(getHeightOfNode(node->left), getHeightOfNode(node->right));

    // 3. Get the balance factor to check if it became unbalanced
    int balance = getBalanceOfNode(node);

    // 4. If unbalanced, we have 4 cases:

    // Case A: Left-Left (LL) -> Right Rotate
    if (balance > 1 && data < node->left->data) {
        return LLRoation(node);
    }

    // Case B: Right-Right (RR) -> Left Rotate
    if (balance < -1 && data > node->right->data) {
        return RRrotation(node);
    }

    // Case C: Left-Right (LR) -> Left + Right Rotate
    if (balance > 1 && data > node->left->data) {
        return LRrotation(node);
    }

    // Case D: Right-Left (RL) -> Right + Left Rotate
    if (balance < -1 && data < node->right->data) {
        return RLrotation(node);
    }

    return node; // Return the unchanged node pointer
}

// Find the node with minimum value in a subtree
Node* getMinNode(Node* root) {
    Node* current = root;

    while (current->left != nullptr) {
        current = current->left;
    }

    return current;
}

// Delete a node from AVL Tree
Node* deleteNode(Node* root, int value) {

    // 1. Normal BST deletion
    if (root == nullptr)
        return root;

    // Search in left subtree
    if (value < root->data) {
        root->left = deleteNode(root->left, value);
    }

    // Search in right subtree
    else if (value > root->data) {
        root->right = deleteNode(root->right, value);
    }

    // Node found
    else {

        // Case 1: No child
        if (root->left == nullptr && root->right == nullptr) {
            delete root;
            return nullptr;
        }

        // Case 2: Only right child
        else if (root->left == nullptr) {
            Node* temp = root->right;
            delete root;
            return temp;
        }

        // Case 3: Only left child
        else if (root->right == nullptr) {
            Node* temp = root->left;
            delete root;
            return temp;
        }

        // Case 4: Two children
        else {
            // Find inorder successor
            Node* temp = getMinNode(root->right);

            // Copy successor's value
            root->data = temp->data;

            // Delete successor
            root->right = deleteNode(root->right, temp->data);
        }
    }

    // 2. Update height
    root->height = 1 + std::max(
        getHeightOfNode(root->left),
        getHeightOfNode(root->right)
    );

    // 3. Calculate balance factor
    int balance = getBalanceOfNode(root);


    // 4. LL Case
    if (balance > 1 &&
        getBalanceOfNode(root->left) >= 0) {

        return LLRoation(root);
    }


    // 5. LR Case
    if (balance > 1 &&
        getBalanceOfNode(root->left) < 0) {

        return LRrotation(root);
    }


    // 6. RR Case
    if (balance < -1 &&
        getBalanceOfNode(root->right) <= 0) {

        return RRrotation(root);
    }


    // 7. RL Case
    if (balance < -1 &&
        getBalanceOfNode(root->right) > 0) {

        return RLrotation(root);
    }

    return root;
}

#include <iostream>
