    int height;
    Node(int val) : data(val), left(nullptr), right(nullptr), height(0) {}
};

int getHeightOfNode(Node* node) {
    return (node == nullptr) ? -1 : node->height;
}

int getBalanceOfNode(Node* node) {
    return (node == nullptr) ? 0 : getHeightOfNode(node->left) - getHeightOfNode(node->right);
}

Node* LLRoation(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = 1 + std::max(getHeightOfNode(y->left), getHeightOfNode(y->right));
    x->height = 1 + std::max(getHeightOfNode(x->left), getHeightOfNode(x->right));
    return x;
}

Node* RRrotation(Node* y) {
    Node* x = y->right;
    Node* T2 = x->left;
    x->left = y;
    y->right = T2;
    y->height = 1 + std::max(getHeightOfNode(y->left), getHeightOfNode(y->right));
    x->height = 1 + std::max(getHeightOfNode(x->left), getHeightOfNode(x->right));
    return x;
}

Node* LRrotation(Node* y) {
    y->left = RRrotation(y->left);
    return LLRoation(y);
}

Node* RLrotation(Node* y) {
    y->right = LLRoation(y->right);
    return RRrotation(y);
}

Node* insert(Node* node, int data) {
    if (node == nullptr) return new Node(data);

    if (data < node->data) {
        node->left = insert(node->left, data);
    } else if (data > node->data) {
        node->right = insert(node->right, data);
    } else {
        return node;
    }

    node->height = 1 + std::max(getHeightOfNode(node->left), getHeightOfNode(node->right));
    int balance = getBalanceOfNode(node);

    if (balance > 1 && data < node->left->data) return LLRoation(node);
    if (balance < -1 && data > node->right->data) return RRrotation(node);
    if (balance > 1 && data > node->left->data) return LRrotation(node);
    if (balance < -1 && data < node->right->data) return RLrotation(node);

    return node;
}

Node* getMinNode(Node* root) {
    Node* current = root;
    while (current->left != nullptr) {
        current = current->left;
    }
    return current;
}

Node* deleteNode(Node* root, int value) {
    if (root == nullptr) return root;

    if (value < root->data) {
        root->left = deleteNode(root->left, value);
    } else if (value > root->data) {
        root->right = deleteNode(root->right, value);
    } else {
        if (root->left == nullptr && root->right == nullptr) {
            delete root;
            return nullptr;
        } else if (root->left == nullptr) {
            Node* temp = root->right;
            delete root;
            return temp;
        } else if (root->right == nullptr) {
            Node* temp = root->left;
            delete root;
            return temp;
        } else {
            Node* temp = getMinNode(root->right);
            root->data = temp->data;
            root->right = deleteNode(root->right, temp->data);
        }
    }

    root->height = 1 + std::max(getHeightOfNode(root->left), getHeightOfNode(root->right));
    int balance = getBalanceOfNode(root);

    if (balance > 1 && getBalanceOfNode(root->left) >= 0) return LLRoation(root);
    if (balance > 1 && getBalanceOfNode(root->left) < 0) return LRrotation(root);
    if (balance < -1 && getBalanceOfNode(root->right) <= 0) return RRrotation(root);
    if (balance < -1 && getBalanceOfNode(root->right) > 0) return RLrotation(root);

    return root;
}

void preOrder(Node* root) {
    if (root != nullptr) {
        std::cout << root->data << " ";
        preOrder(root->left);
        preOrder(root->right);
    }
}

